// 1. Constantes e Catálogos Base
const potters = [
    'António Silva', 'Pedro Martins', 'Carlos Alberto', 'João Rosa',
    'André Santos', 'Rui Pedro', 'Armindo Matos', 'Gonçalo Duarte'
];

const categories = [
    // Peças Normais (Temperatura entre 950 ºC e 1000 ºC)
    'Pote Triplo 30x30', 'Caneca Terracota 15x10', 'Jarra Moura 70x30',
    'Vaso Jardineira 40x20', 'Prato de Fundo 35x4', 'Talha Larga 80x60',
    'Taça Redonda 35x35', 'Ânfora 50x30',
    // Peças Vidradas (Temperatura > 1000 ºC)
    'Pote Vidrado 30x30', 'Caneca Vidrada 30x20', 'Jarra Vidrada 60x30',
    'Vaso Vidrado 30x40', 'Prato Vidrado 28x5', 'Talha Vidrada 80x60',
    'Vaso de Jardim Marroquino Vidrado 70x50', 'Ânfora Grega Vidrada 50x30'
];

// Estritamente Forno A e Forno B
const kilns = [
    { id: 'FORNO_A', num: 1 },
    { id: 'FORNO_B', num: 2 }
];

const randomItem = (arr) => arr[Math.floor(Math.random() * arr.length)];
const randomInt = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;
const randomFloat = (min, max, dec) => parseFloat((Math.random() * (max - min) + min).toFixed(dec));
const gaussianNoise = (stdDev = 1) => (Math.random() + Math.random() + Math.random() - 1.5) * 2 * stdDev;

const now = new Date();
const currentYear = now.getFullYear();
const productionDate = now.toISOString().split('T')[0];
const batchCount = randomInt(2, 6);

let telemetryBatches = [];
let csvContent = "batch_id,production_date,potter_name,category,total_qty,broken_pieces,approved_pieces\n";

for (let i = 0; i < batchCount; i++) {
    const selectedKiln = randomItem(kilns);
    const firingId = randomInt(100, 999);

    // Formato: LOT-F1-2026-XXXX ou LOT-F2-2026-XXXX
    const batchId = `LOT-F${selectedKiln.num}-${currentYear}-${String(randomInt(0, 9999)).padStart(4, '0')}`;
    const category = randomItem(categories);
    const potter = randomItem(potters);

    // Identificação de regime de cozedura
    const isGlazed = /vidrad[ao]/i.test(category);

    let maxTemp;
    let durationHours;
    let tempAnomaly = false;

    if (isGlazed) {
        // Regime Vidrado: > 1000 ºC
        const noise = gaussianNoise(3.5);
        maxTemp = 1010.0 + randomFloat(5.0, 65.0, 2) + noise;
        durationHours = randomFloat(8.5, 13.0, 2);

        if (Math.random() < 0.10) {
            maxTemp += randomFloat(15.0, 45.0, 2);
            tempAnomaly = true;
        }
    } else {
        // Regime Normal: ronda 975 ºC
        const noise = gaussianNoise(3.0);
        maxTemp = 975.0 + randomFloat(-22.0, 22.0, 2) + noise;
        durationHours = randomFloat(5.5, 8.5, 2);

        if (Math.random() < 0.08) {
            maxTemp = 1001.0 + randomFloat(2.0, 30.0, 2);
            tempAnomaly = true;
        }
    }

    maxTemp = parseFloat(maxTemp.toFixed(2));

    // Consumo de Gás (m³): base horária média
    const m3PerHour = isGlazed ? randomFloat(22.0, 26.5, 2) : randomFloat(18.0, 22.0, 2);
    const gasConsumedM3 = parseFloat((durationHours * m3PerHour).toFixed(2));

    // Regras de Produção e Quebras
    const totalQty = randomInt(30, 200);
    let broken;

    if (tempAnomaly) {
        const defectPercent = randomFloat(0.20, 0.50, 2);
        broken = Math.min(totalQty, Math.max(5, Math.floor(totalQty * defectPercent)));
    } else {
        if (Math.random() < 0.08) {
            broken = randomInt(4, 15);
        } else {
            broken = randomInt(0, Math.max(1, Math.floor(totalQty * 0.04)));
        }
    }

    const approved = Math.max(0, totalQty - broken);

    // a) Linha CSV
    csvContent += `${batchId},${productionDate},${potter},${category},${totalQty},${broken},${approved}\n`;

    // b) Telemetria JSON (com consumo real em m3)
    telemetryBatches.push({
        batch_id: batchId,
        firing_id: firingId,
        kiln_id: selectedKiln.id,
        max_temp_recorded: maxTemp,
        firing_duration_hours: durationHours,
        gas_consumed_m3: gasConsumedM3,
        temp_anomaly: tempAnomaly,
        rate_anomaly: false,
        firing_anomaly: tempAnomaly
    });
}

const jsonPayload = JSON.stringify(telemetryBatches, null, 2);

// Saída 1: CSV de Produção | Saída 2: JSON de Telemetria | Saída 3: Telemetria via MQTT
return [
    { payload: csvContent },
    { payload: jsonPayload },
    { payload: jsonPayload }
];

const now = new Date();
const year = now.getFullYear();
const month = String(now.getMonth() + 1).padStart(2, '0');

// Endpoint de preços diários da REN com parâmetros obrigatórios
msg.url = `https://servicebus.ren.pt/datahubapi/gas/GasMarketPricesDaily?culture=pt-PT&year=${year}&month=${month}`;
msg.method = "GET";

return msg;

let eurPerMwh = 35.00; // Valor padrão de contingência

// 1. Extração do preço diário mais recente do JSON da REN
if (Array.isArray(msg.payload) && msg.payload.length > 0) {
    try {
        // Encontra o último registo com valor numérico válido
        for (let i = msg.payload.length - 1; i >= 0; i--) {
            const entry = msg.payload[i];
            const price = entry.price ?? entry.valor ?? entry.value ?? entry.Price;
            if (price !== null && !isNaN(price)) {
                eurPerMwh = parseFloat(price);
                break;
            }
        }
    } catch (err) {
        node.warn("Erro ao ler JSON da REN, a utilizar valor padrão: " + err.message);
    }
}

// 2. Fórmulas de conversão física e regulada
// 1 MWh = 1000 kWh
const eurPerKwh = eurPerMwh / 1000.0;

// Poder Calorífico Superior (PCS padrão Gás Natural Portugal): 1 m³ ≈ 10.82 kWh
const pcsCalorific = 10.82;

// Custo bruto do m³
const gasM3Price = parseFloat((eurPerKwh * pcsCalorific).toFixed(4));

// Tarifas de Acesso às Redes (TAR) e Taxa de Carbono/ISP reguladas pela ERSE
const networkAccessTax = 0.055; // 5.5%
const carbonTaxPerM3 = 0.038;   // 0.038 €/m³

const today = new Date().toISOString().split('T')[0];

// 3. Montar a estrutura do XML
const xmlContent = `<?xml version="1.0" encoding="UTF-8"?>
<market_energy_cost>
    <metadata>
        <data_source>REN_DATAHUB_OFFICIAL</data_source>
        <market_zone>MIBGAS_PT</market_zone>
        <reference_date>${today}</reference_date>
        <currency>EUR</currency>
    </metadata>
    <gas_tariffs>
        <market_price_eur_mwh>${eurPerMwh.toFixed(2)}</market_price_eur_mwh>
        <market_price_eur_kwh>${eurPerKwh.toFixed(4)}</market_price_eur_kwh>
        <calorific_value_pcs>${pcsCalorific}</calorific_value_pcs>
        <gas_m3_price>${gasM3Price}</gas_m3_price>
        <network_access_tax_pct>${networkAccessTax}</network_access_tax_pct>
        <carbon_tax_eur_m3>${carbonTaxPerM3}</carbon_tax_eur_m3>
    </gas_tariffs>
</market_energy_cost>`;

return {
    payload: xmlContent,
    filename: "C:\\PERSONAL\\ISI\\clay-sense-ETL\\data\\energy_tariffs.xml"
};

// Valores médios históricos/regulados para contingência
const fallbackMarketPriceMwh = 35.00;
const fallbackMarketPriceKwh = 0.0350;
const fallbackPcs = 10.82;
const fallbackM3Price = 0.3787;
const fallbackTaxPct = 0.055;
const fallbackCarbonTax = 0.038;

// Montar estrutura XML idêntica à esperada pelo Pentaho
const xmlContent = `<?xml version="1.0" encoding="UTF-8"?>
<market_specifications>
  <specification>
    <market_price_eur_mwh>${fallbackMarketPriceMwh.toFixed(2)}</market_price_eur_mwh>
    <market_price_eur_kwh>${fallbackMarketPriceKwh.toFixed(4)}</market_price_eur_kwh>
    <calorific_value_pcs>${fallbackPcs.toFixed(2)}</calorific_value_pcs>
    <gas_m3_price>${fallbackM3Price.toFixed(4)}</gas_m3_price>
    <network_access_tax_pct>${fallbackTaxPct.toFixed(3)}</network_access_tax_pct>
    <carbon_tax_eur_m3>${fallbackCarbonTax.toFixed(3)}</carbon_tax_eur_m3>
  </specification>
</market_specifications>`;

msg.payload = xmlContent;
node.warn("Aviso: Falha na API da REN. A utilizar valores de contingência (Fallback XML).");

return msg;
